  "java/Application.java.ejs": "package <%= project.basePackage %>;\n\n<%- imports %>\n\n@<%= type('org.springframework.boot.autoconfigure.SpringBootApplication') %>\npublic class <%= project.applicationClass %> {\n\n    public static void main(String[] args) {\n        <%= type('org.springframework.boot.SpringApplication') %>.run(<%= project.applicationClass %>.class, args);\n    }\n}\n",
  "java/generated/AgentConfiguration.java.ejs": "// Managed by gen-agent: changes here are overwritten. Edit agent.yaml and regenerate.\npackage <%= project.generatedPackage %>;\n\n<%- imports %>\n\n/** Wires the chat client: system prompt, conversation memory and the tools the model may call. */\n@<%= type('org.springframework.context.annotation.Configuration') %>(proxyBeanMethods = false)\n<%_ if (features.httpTools) { _%>\n@<%= type('org.springframework.boot.context.properties.EnableConfigurationProperties') %>({AgentProperties.class<%_ for (const tool of tools) { if (tool.kind === 'http') { _%>, <%= type(`${project.generatedPackage}.tool.${tool.className}Properties`) %>.class<%_ } } _%>})\n<%_ } else { _%>\n@<%= type('org.springframework.boot.context.properties.EnableConfigurationProperties') %>(AgentProperties.class)\n<%_ } _%>\nclass AgentConfiguration {\n\n    @<%= type('org.springframework.context.annotation.Bean') %>\n    <%= type('org.springframework.ai.chat.memory.ChatMemory') %> chatMemory(AgentProperties properties) {\n        return <%= type('org.springframework.ai.chat.memory.MessageWindowChatMemory') %>.builder()\n                .chatMemoryRepository(new <%= type('org.springframework.ai.chat.memory.InMemoryChatMemoryRepository') %>())\n                .maxMessages(properties.memory().window())\n                .build();\n    }\n\n    @Bean\n    <%= type('org.springframework.ai.chat.client.ChatClient') %> chatClient(\n            ChatClient.Builder builder,\n            ChatMemory chatMemory,\n            AgentProperties properties<%_ for (const tool of tools) { _%>,\n            <%= type(`${project.generatedPackage}.tool.${tool.className}`) %> <%= tool.methodName %>Tool<%_ } _%>) {\n        return builder.defaultSystem(properties.systemPrompt())\n                .defaultAdvisors(<%= type('org.springframework.ai.chat.client.advisor.MessageChatMemoryAdvisor') %>.builder(chatMemory).build())\n<%_ if (tools.length > 0) { _%>\n                .defaultTools(<%= tools.map((tool) => `${tool.methodName}Tool`).join(', ') %>)\n<%_ } _%>\n                .build();\n    }\n}\n",
  "java/generated/AgentProperties.java.ejs": "// Managed by gen-agent: changes here are overwritten. Set the values in application.yml.\npackage <%= project.generatedPackage %>;\n\n<%- imports %>\n\n/**\n * Agent settings bound from the {@code agent} section of {@code application.yml}.\n *\n * @param systemPrompt the system prompt, kept in a resource file so it can be versioned and reviewed like code\n * @param memory how much of the conversation is sent back to the model\n */\n@<%= type('org.springframework.boot.context.properties.ConfigurationProperties') %>(\"agent\")\npublic record AgentProperties(<%= type('org.springframework.core.io.Resource') %> systemPrompt, Memory memory) {\n\n    /**\n     * @param window number of recent messages kept per conversation\n     */\n    public record Memory(int window) {}\n}\n",
  "java/generated/chat/ChatController.java.ejs": "// Managed by gen-agent: changes here are overwritten.\npackage <%= project.generatedPackage %>.chat;\n\n<%- imports %>\n\n@<%= type('org.springframework.web.bind.annotation.RestController') %>\n@<%= type('org.springframework.web.bind.annotation.RequestMapping') %>(\"/api/chat\")\nclass ChatController {\n\n    private final ChatService chatService;\n\n    ChatController(ChatService chatService) {\n        this.chatService = chatService;\n    }\n\n    @<%= type('org.springframework.web.bind.annotation.PostMapping') %>\n    ChatMessageResponse chat(@<%= type('jakarta.validation.Valid') %> @<%= type('org.springframework.web.bind.annotation.RequestBody') %> ChatMessageRequest request) {\n        return chatService.reply(request);\n    }\n}\n",
  "java/generated/chat/ChatExceptionHandler.java.ejs": "// Managed by gen-agent: changes here are overwritten.\npackage <%= project.generatedPackage %>.chat;\n\n<%- imports %>\n\n/**\n * Answers every error as an RFC 9457 problem detail. Spring MVC errors (validation…) keep their status; anything else\n * becomes a generic 500 whose details stay in the logs, never in the response.\n */\n@<%= type('org.springframework.web.bind.annotation.RestControllerAdvice') %>\nclass ChatExceptionHandler extends <%= type('org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler') %> {\n\n    private static final <%= type('org.slf4j.Logger') %> log = <%= type('org.slf4j.LoggerFactory') %>.getLogger(ChatExceptionHandler.class);\n\n    @<%= type('org.springframework.web.bind.annotation.ExceptionHandler') %>(Exception.class)\n    <%= type('org.springframework.http.ProblemDetail') %> handleUnexpected(Exception exception) {\n        log.error(\"The agent could not answer\", exception);\n        ProblemDetail problem = ProblemDetail.forStatusAndDetail(\n                <%= type('org.springframework.http.HttpStatus') %>.INTERNAL_SERVER_ERROR, \"The agent could not answer. Try again later.\");\n        problem.setTitle(\"Agent error\");\n        return problem;\n    }\n}\n",
