  "java/generated/chat/ChatMessageResponse.java.ejs": "// Managed by gen-agent: changes here are overwritten.\npackage <%= project.generatedPackage %>.chat;\n\n/**\n * The agent's reply.\n *\n * @param conversationId conversation to send with the next message to keep the context\n * @param reply what the agent answers\n<%_ if (prompt.aiDisclosure) { _%>\n * @param aiGenerated always {@code true}: tells clients the reply comes from an AI, as the EU AI Act requires\n<%_ } _%>\n */\n<%_ if (prompt.aiDisclosure) { _%>\nrecord ChatMessageResponse(String conversationId, String reply, boolean aiGenerated) {\n\n    ChatMessageResponse(String conversationId, String reply) {\n        this(conversationId, reply, true);\n    }\n}\n<%_ } else { _%>\nrecord ChatMessageResponse(String conversationId, String reply) {}\n<%_ } _%>\n",
  "java/generated/chat/ChatService.java.ejs": "// Managed by gen-agent: changes here are overwritten.\npackage <%= project.generatedPackage %>.chat;\n\n<%- imports %>\n\n/** Sends a user message to the model within its conversation, so earlier messages are remembered. */\n@<%= type('org.springframework.stereotype.Service') %>\nclass ChatService {\n\n    private final <%= type('org.springframework.ai.chat.client.ChatClient') %> chatClient;\n\n    ChatService(ChatClient chatClient) {\n        this.chatClient = chatClient;\n    }\n\n    ChatMessageResponse reply(ChatMessageRequest request) {\n        String conversationId = request.conversationId() != null\n                ? request.conversationId()\n                : <%= type('java.util.UUID') %>.randomUUID().toString();\n        String reply = chatClient\n                .prompt()\n                .user(request.message())\n                .advisors(advisor -> advisor.param(<%= type('org.springframework.ai.chat.memory.ChatMemory') %>.CONVERSATION_ID, conversationId))\n                .call()\n                .content();\n        return new ChatMessageResponse(conversationId, reply);\n    }\n}\n",
